function assertOrder(versions) {
  for (let i = 0; i < versions.length; i++) {
    for (let j = 0; j < versions.length; j++) {
      assert.equal(compareVersions(versions[i], versions[j]), Math.sign(i - j),
        `${versions[i]} vs ${versions[j]}`);
    }
  }
}

test('SemVer precedence example, in both directions and including equality', () => {
  assertOrder([
    '1.0.0-alpha',
    '1.0.0-alpha.1',
    '1.0.0-alpha.beta',
    '1.0.0-beta',
    '1.0.0-beta.2',
    '1.0.0-beta.11',
    '1.0.0-rc.1',
    '1.0.0',
  ]);
});

test('core version takes precedence over pre-release identifiers', () => {
  assertOrder(['1.0.0', '1.0.1-alpha', '1.1.0-alpha', '2.0.0-alpha']);
});

test('numeric identifiers precede non-numeric identifiers, which use ASCII order', () => {
  assertOrder(['1.0.0-2', '1.0.0-10', '1.0.0-1a', '1.0.0-A', '1.0.0-a', '1.0.0-a-b']);
});

test('build metadata does not affect precedence', () => {
  for (const version of ['1.2.3', '1.2.3-alpha.1', '1.2.3-alpha-beta']) {
    for (const a of ['', '+build.1', '+other-2.3']) {
      for (const b of ['', '+build.1', '+other-2.3']) {
        assert.equal(compareVersions(version + a, version + b), 0);
      }
    }
  }
  assertOrder(['1.0.0-alpha+z', '1.0.0+0', '1.0.1-alpha+1']);
});

test('numeric identifiers are compared without loss of precision', () => {
  assertOrder(['1.0.0-9007199254740992', '1.0.0-9007199254740993']);
  assertOrder(['9007199254740992.0.0', '9007199254740993.0.0']);
  assertOrder(['1.9007199254740992.0', '1.9007199254740993.0']);
  assertOrder(['1.0.9007199254740992', '1.0.9007199254740993']);
});
